function activity(S,R){const u=state(S);let all=activityData(S,R),list=searchRows(all,u.eventQ,['title','protocol','symbol','out','incoming']);if(u.eventType!=='all')list=list.filter(x=>x.type===u.eventType);if(u.eventStatus!=='all')list=list.filter(x=>x.status===u.eventStatus);if(u.eventAsset!=='all')list=list.filter(x=>x.symbol===u.eventAsset||x.inputSymbol===u.eventAsset);if(u.eventDays!=='all'){const now=DEMO()?SAMPLE_TIME:Date.now();list=list.filter(x=>now-x.at<Number(u.eventDays)*86400000);}list=stableSort(list,'at');
 const groups=new Map();for(const ev of list){const day=dateLabel(ev.at);if(!groups.has(day))groups.set(day,[]);groups.get(day).push(ev);}
 return title('Actividad','Qué pasó, con qué activos y en qué estado.',btn('Exportar movimientos','ux-export-events','download'))+
 `<div class="r-toolbar">${input('eventQ','Buscar actividad',u.eventQ,'Buscar activo, protocolo o acción…')}${select('eventType','Tipo de movimiento',u.eventType,[['all','Todos los movimientos'],['swap','Intercambios'],['receive','Entradas'],['send','Salidas'],['deposit','Depósitos'],['withdraw','Retiros']])}${select('eventStatus','Estado',u.eventStatus,[['all','Todos los estados'],['confirmed','Confirmadas'],['submitted','Pendientes'],['failed','Fallidas']])}${select('eventDays','Período',u.eventDays,[['all','Todo el historial'],['1','Últimas 24 h'],['7','Últimos 7 días'],['30','Últimos 30 días']])}</div>`+
 `<div class="r-result-head"><span>${list.length} movimientos</span><div>${select('eventAsset','Activo',u.eventAsset,[['all','Todos los activos'],['SOL','SOL'],['USDC','USDC']])}${sampleLabel()}</div></div>`+
 (list.length?`<div class="r-timeline">${[...groups].map(([day,evs])=>`<section><h2>${e(day)}<span>${evs.length} movimientos</span></h2><div class="r-panel">${eventsList(evs)}</div></section>`).join('')}</div>`:empty('No hay movimientos con estos filtros','Probá otro activo, período o estado.',btn('Limpiar filtros','ux-reset','refresh','secondary','data-scope="event"')));}
function tokenPage(S,R){return title('PULP','El token del ecosistema. Estado y condiciones visibles.',go('Ver tesorería','governance','vote'))+
 `<div class="r-token-header"><img src="assets/brand/pulp-icon.svg" alt="" width="72" height="72"><div><h2>PULP <span>Token oficial</span></h2><p>Una identidad para el ecosistema Pulp.</p></div>${pill('No emitido','warning')}</div>`+
 statsRow([['Precio','—','Sin mercado oficial'],['Capitalización','—','No calculable sin emisión'],['Suministro','—','Pendiente de parámetros'],['Liquidez','—','No desplegada']])+
 `<div class="r-grid two">${section('Estado de emisión',breakdown([['Red propuesta','Solana'],['Mint oficial',e(S.config.pulpMint||'Sin desplegar')],['Tesorería',e(S.config.treasury||'Sin configurar')],['Distribución y vesting','Parámetros pendientes de aprobación'],['Autoridades','Por publicar antes de emitir']]),pill('Transparencia','purple'))}${section('Documentación del token',`<div class="r-document-list">${[['Identidad y utilidad','Los servicios definen el papel del token.'],['Distribución y desbloqueos','Asignaciones y condiciones antes de lanzar.'],['Tesorería y recompra','Separadas de ingresos y liquidez.']].map(([h,p])=>`<article>${I('document')}<div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div>`)}</div><details class="r-disclosure"><summary>${I('info','sm')}Sobre estos datos</summary><p>El token oficial no fue emitido. No se asigna un precio, una oferta en circulación o un market cap ficticio. Los descuentos y mecanismos económicos necesitan parámetros públicos antes del lanzamiento.</p></details>`;}
function governancePage(S,R){const u=state(S),d=val(R('governance','governance/list'))||{proposals:[]};const ps=d.proposals||[];return title('Gobernanza','Propuestas, contexto y decisiones de la comunidad.',btn('Crear consulta','proposal-form','plus','primary'))+
 `<div class="r-governance-summary">${metric('Propuestas',String(ps.length),'Consultas disponibles','vote')}${metric('Tipo de participación','Consulta local','No ejecuta transacciones','shield')}${metric('Tesorería on-chain','Por configurar','Control multifirma independiente','wallet')}</div>`+
 section('Propuestas de la comunidad',ps.length?`<div class="r-proposals">${ps.map(p=>`<button data-action="ux-detail" data-kind="proposal" data-id="${e(p.id)}"><span class="r-app-icon">${I('vote')}</span><span><small>${pill(p.endsAt>Date.now()?'Abierta':'Cerrada',p.endsAt>Date.now()?'purple':'neutral')}</small><strong>${e(p.title.replace(/^Ejemplo · /,''))}</strong><p>${e(p.description.slice(0,160))}</p><small>Cierre: ${dateLabel(p.endsAt)} · consulta no vinculante</small></span>${I('arrow')}</button>`).join('')}</div>`:empty('Todavía no hay propuestas','Las consultas aparecerán con su contexto, estado y fecha de cierre.'),sampleLabel())+
 `<details class="r-disclosure"><summary>${I('shield','sm')}Gobernanza ejecutable y multifirma</summary><p>Una consulta local no mueve fondos ni representa el voto de una DAO. Las operaciones de tesorería se revisan por separado.</p>${go('Abrir administración de Squads','governance-onchain','vote','secondary')}</details>`;}
function alertsPage(S,R){const d=val(R('v4inbox','v4/inbox'))||{items:[]},rules=val(R('v4rules','v4/alerts'))||{rules:[]};return title('Alertas e inbox','Las señales que elegís, con su contexto.',btn('Nueva regla','ux-new-alert','plus','primary'))+
 `<div class="r-grid two">${section('Inbox',d.items.length?`<div class="r-inbox">${d.items.map(n=>`<article class="${n.read?'read':''}"><span class="r-event-icon">${I(n.kind==='price'?'chart':'radar')}</span><div><h3>${e(n.kind==='price'?'Precio observado':'Movimiento de wallet')}</h3><p>${e(n.message.replace(/^Ejemplo de (aviso|alerta de precio):? ?/,''))}</p><small>${dateLabel(n.at)} · ${timeLabel(n.at)}</small></div>${n.read?pill('Leída'):btn('Marcar leída','v4-inbox-read','check','ghost',`data-id="${e(n.id)}"`)}</article>`).join('')}</div>`:empty('Estás al día','Tus nuevas notificaciones aparecerán acá.'),btn('Marcar todas','v4-inbox-read','check','ghost','data-id="all"'))}${section('Tus reglas',rules.rules.length?`<div class="r-rules">${rules.rules.map(r=>`<article><div><strong>${e(r.label||'Regla sin nombre')}</strong><p>${e(r.kind==='wallet'?'Actividad de wallet':'Condición de precio')}</p>${pill('Borrador local')}</div>${btn('Eliminar','v4-delete-rule','trash','ghost',`data-id="${e(r.id)}"`)}</article>`).join('')}</div>`:empty('Definí qué seguir','Podés preparar una regla sin activar notificaciones externas.'))}</div>`+
 `<div class="r-learning-grid">${[['bell','Inbox','Eventos organizados por fecha.'],['globe','Canales','Telegram y Discord requieren configuración del operador.'],['shield','Control','Tus reglas no autorizan operaciones financieras.']].map(([i,h,p])=>`<article><span>${I(i)}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div>`;}
function strategiesPage(S,R){const d=val(R('v4strategies','v4/strategies'))||{strategies:[]};return title('Estrategias','Seguir, preparar y ejecutar son cosas diferentes.',btn('Crear borrador','ux-new-strategy','plus','primary'))+
 `<div class="r-strategy-types">${[['radar','Seguir una wallet','Observar movimientos sin copiar automáticamente.'],['chart','Compra periódica','Definir activo, frecuencia e importe.'],['shield','Límites claros','Revisión, exposición y firma por operación.']].map(([i,h,p])=>`<article>${I(i)}<h2>${h}</h2><p>${p}</p></article>`).join('')}</div>`+
 section('Tus estrategias',d.strategies.length?table(['Nombre','Tipo','Importe','Límite diario','Estado',''],d.strategies.map(s=>[e(s.name),e(s.kind==='dca'?'Compra periódica':'Seguimiento'),e(s.amount)+' USDC',e(s.maxDailyUsdc??'—')+' USDC',pill('Borrador local'),btn('Eliminar','v4-delete-strategy','trash','ghost',`data-id="${e(s.id)}"`)])):empty('No hay estrategias guardadas','Prepará un borrador con sus límites. No se ejecuta automáticamente.'))+
 section('Ejecución y resultados',`<div class="r-copy"><p>Una estrategia guardada no es una orden enviada. Cada operación necesita cotización actual, revisión y firma. El resultado de un creador y el resultado de su seguidor deben medirse por separado.</p><div class="r-actions">${noop('Preparar ejecución','swap')}<span class="r-small">Automatización desatendida: no habilitada.</span></div></div>`);}
const renderers={home,intelligence:radar,'wallet-inspector':walletProfile,trade,earn,liquidity,launchpad,'launch-planner':launchWizard,launchlab:launchlabOverview,portfolio,activity,token:tokenPage,governance:governancePage,alerts:alertsPage,strategies:strategiesPage};
export function renderProduct(S,R){state(S);if(S.route==='ui-kit')return renderPage(S,R)+productKit(S);if(S.route==='token'&&!DEMO())return renderPage(S,R);if(S.route==='settings')return preferences(S,R);if(S.route==='connections')return renderPage({...S,route:'settings'},R);const fn=renderers[S.route];if(!fn)return null;return `<div class="r-product" data-product-route="${e(S.route)}">${fn(S,R)}</div>`;}
export function renderProductDialog(S,R){const m=S.modal;if(m?.kind!=='product')return null;let body='',heading='Detalles';
 if(m.view==='method'){heading='Cómo leer el radar';body=`<div class="r-method-grid single"><article><h3>Resultados con límites</h3><p>Se observa una wallet, no toda la cartera de una persona. Transferencias sin costo conocido, ventas fuera de ventana y fondos externos limitan el cálculo.</p></article><article><h3>Cobertura antes que ranking</h3><p>Sin cobertura suficiente no hay puntuación. Los datos de esta presentación son una muestra, no recomendaciones.</p></article><article><h3>El seguidor tiene otro resultado</h3><p>Deslizamiento, comisiones, latencia y liquidez modifican la ejecución. No se promete copiar una rentabilidad.</p></article></div>`;}
 if(m.view==='compare'){heading='Comparar wallets';const ws=radarData(S,R).filter(w=>state(S).compare.includes(w.id));body=table(['Métrica',...ws.map(w=>e(w.name))],[['Estilo',...ws.map(w=>e(w.category))],['Resultado bruto',...ws.map(w=>signed(w.pnl))],['Aciertos',...ws.map(w=>pct(w.win))],['Caída máxima',...ws.map(w=>pct(w.drawdown))],['Movimientos',...ws.map(w=>number(w.activity))],['Cobertura',...ws.map(w=>pct(w.coverage))],['Observación',...ws.map(w=>e(w.days)+' días')]])+sampleContext();}
 if(m.view==='event'){const ev=activityData(S,R).find(x=>x.id===m.id);heading=ev?.title||'Movimiento';body=ev?`<div class="r-detail-event"><span class="r-event-icon">${I('history')}</span>${statusPill(ev.status)}</div>`+breakdown([['Fecha',e(dateLabel(ev.at)+' · '+timeLabel(ev.at))],['Protocolo',e(ev.protocol)],['Sale',e(ev.out||'—')],['Entra',e(ev.incoming||'—')],['Costo de red',ev.fee==null?'Por consultar':number(ev.fee,9)+' SOL'],['Comprobante',ev.signature?e(ev.signature):'No emitido · evento de muestra'],['Estado',statusPill(ev.status)]]):empty('Movimiento no encontrado','Actualizá el historial.');if(ev?.signature)body+=btn('Copiar firma','copy','copy','secondary',`data-value="${e(ev.signature)}"`);}
 if(m.view==='projectDoc'){const p=projectsData(S,R).find(p=>p.id===m.id);heading='Ficha de '+(p?.name||'proyecto');body=p?`<div class="r-copy"><p>${e(p.description)}</p><h3>Información necesaria para lanzar</h3><p>Contrato, distribución, vesting, permisos, uso de fondos y control de liquidez deben ser verificables. Esta ficha es un ejemplo local, sin oferta pública.</p></div>`+breakdown([['Categoría',e(p.category)],['Ticker',e(p.symbol)],['Estado visual',statusPill(p.status)],['Contrato','No emitido']]):empty('Ficha no disponible','Seleccioná un proyecto del catálogo.');}
 if(m.view==='address'){heading='Consultar una dirección';body=`<form class="b-form" data-form="ux-address">${field('ux-address','address','Dirección pública Solana','',{attrs:'required spellcheck="false" maxlength="44"',placeholder:'Dirección de wallet o pool'})}<button class="btn btn-primary" type="submit">Validar dirección</button><p class="r-small">En esta presentación la dirección se guarda como referencia local, sin consultar balances.</p></form>`;}
 if(m.view==='deleteDraft'){heading='Eliminar borrador';body=`<div class="r-copy"><p>Se eliminará este borrador del espacio local. Esta acción no afecta tokens ni contratos.</p></div>${btn('Eliminar borrador','ux-delete-draft-confirm','trash','secondary',`data-id="${e(m.id)}"`)}`;}
 if(m.view==='proposal'){const d=val(R('governance','governance/list'));const p=d?.proposals?.find(x=>x.id===m.id);heading=p?.title||'Propuesta';body=p?`<div class="r-copy"><p>${e(p.description)}</p></div>`+breakdown([['Autor',e(p.author)],['Cierre',e(dateLabel(p.endsAt))],['Votos',number(p.votes?.length||0)],['Alcance','Consulta local · no ejecutable']])+`<div class="r-actions">${noop('Votar a favor','vote')}<button class="btn btn-secondary" disabled>Votar en contra</button></div>`:empty('Propuesta no disponible','Volvé a la lista de consultas.');}
 if(m.view==='alert'){heading='Nueva regla';body=`<form class="b-form" data-form="v4-alert">${field('v4-alert','label','Nombre','',{attrs:'required maxlength="60"'})}${field('v4-alert','kind','Tipo','wallet',{select:[['wallet','Actividad de wallet'],['above','Precio mayor o igual'],['below','Precio menor o igual']]})}${field('v4-alert','address','Dirección pública','',{attrs:'spellcheck="false"'})}${field('v4-alert','mint','Mint de token','',{attrs:'spellcheck="false"'})}${field('v4-alert','threshold','Umbral de precio USD','',{type:'number',attrs:'min="0" step="any"'})}<button class="btn btn-primary" type="submit">Guardar regla local</button><p class="r-small">No envía notificaciones desde esta presentación.</p></form>`;}
 if(m.view==='strategy'){heading='Borrador de estrategia';body=`<form class="b-form" data-form="v4-strategy">${field('v4-strategy','name','Nombre','',{attrs:'required maxlength="60"'})}${field('v4-strategy','kind','Tipo','dca',{select:[['dca','Compra periódica'],['copy','Seguir wallet']]})}${field('v4-strategy','source','Wallet de seguimiento','',{attrs:'spellcheck="false"'})}${field('v4-strategy','outputMint','Token a observar','',{attrs:'spellcheck="false"'})}${field('v4-strategy','intervalHours','Intervalo (horas)','24',{type:'number',attrs:'min="1" max="720" required'})}${field('v4-strategy','amount','Importe USDC','10',{type:'number',attrs:'min="0.01" step="0.01" required'})}${field('v4-strategy','maxDailyUsdc','Límite diario USDC','30',{type:'number',attrs:'min="0.01" step="0.01" required'})}<button class="btn btn-primary" type="submit">Guardar borrador</button><p class="r-small">No se programa ninguna operación automática.</p></form>`;}
 return{title:heading,body,wide:m.view==='compare'};
}
export function productBindings(C){const{S,R,api,render,toast,download,openModal,closeModal,clearData}=C;state(S);
 const save=()=>persist(S);const modal=(view,id)=>openModal('product',{view,id});
 const actions={
 'ux-tab':el=>{const key=el.dataset.key;if(!Object.hasOwn(state(S),key)&&!['poolDetailTab'].includes(key))return;S.ux[key]=el.dataset.value;save();},
 'ux-favorite':el=>{const key=el.dataset.kind+'Favorites';if(!['walletFavorites','poolFavorites','marketFavorites','projectFavorites'].includes(key))return;const id=el.dataset.id;S.ux[key]=S.ux[key].includes(id)?S.ux[key].filter(x=>x!==id):[...S.ux[key],id];save();},
 'ux-new-project':()=>{S.ux.launch={...defaults().launch};S.ux.launchStep=0;S.ux.launchErrors=[];save();location.hash='#/launch-planner';},
 'ux-only-favorites':()=>{S.ux.radarOnlyFavorites=!S.ux.radarOnlyFavorites;save();},
 'ux-profile':el=>{S.ux.walletId=el.dataset.id;save();location.hash='#/wallet-inspector?id='+encodeURIComponent(el.dataset.id);},
 'ux-detail':el=>modal(el.dataset.kind,el.dataset.id),
 'ux-method':()=>modal('method'),
 'ux-project-doc':el=>modal('projectDoc',el.dataset.id),
 'ux-compare-add':el=>{const id=el.dataset.id;if(S.ux.compare.includes(id))S.ux.compare=S.ux.compare.filter(x=>x!==id);else if(S.ux.compare.length>=3){toast('Podés comparar hasta tres wallets.');return;}else S.ux.compare.push(id);save();},
 'ux-compare':()=>{if(S.ux.compare.length<2){toast('Elegí al menos dos wallets para comparar.');return;}modal('compare');},
 'ux-clear-compare':()=>{S.ux.compare=[];save();},
 'ux-save-view':()=>{const u=S.ux;u.savedViews=[...u.savedViews,{name:'Vista '+(u.savedViews.length+1),q:u.radarQ,category:u.radarCategory,sort:u.radarSort,period:u.radarPeriod,favorites:u.radarOnlyFavorites}].slice(-10);save();toast('Vista guardada en este navegador.');},
 'ux-reset':el=>{const scope=el.dataset.scope;for(const [k,v] of Object.entries(defaults()))if(k.startsWith(scope)&&!k.endsWith('Favorites'))S.ux[k]=v;save();},
 'ux-open-address':()=>modal('address'),
 'ux-new-alert':()=>modal('alert'),
 'ux-new-strategy':()=>modal('strategy'),
 'ux-wizard-prev':()=>{S.ux.launchStep=Math.max(0,S.ux.launchStep-1);S.ux.launchErrors=[];save();},
 'ux-export-plan':()=>{const errors=validateLaunch(S.ux.launch,3);if(errors.length){S.ux.launchErrors=errors;toast('Completá el plan y revisá la distribución antes de exportar.');return;}download('Pulp-plan-proyecto.json',{format:'pulp-launch-plan-ui',mode:DEMO()?'example-local':'draft-local',issued:false,plan:S.ux.launch});},
 'ux-load-draft':el=>{const d=S.workspace.drafts.find(x=>x.id===el.dataset.id);if(!d)return;S.ux.launch={...defaults().launch,...d,...d.uiPlan};S.ux.launchStep=0;S.ux.launchErrors=[];save();location.hash='#/launch-planner';},
 'ux-delete-draft':el=>modal('deleteDraft',el.dataset.id),
 'ux-delete-draft-confirm':async el=>{S.workspace.drafts=S.workspace.drafts.filter(x=>x.id!==el.dataset.id);const d=await api('account/save',S.workspace,true);S.workspace=d.workspace;closeModal(true);toast('Borrador eliminado.');},
 'ux-export-portfolio':()=>{const d=portfolioData(S,R);download('Pulp-portfolio.json',{source:DEMO()?'Ejemplo local':'Proveedor conectado',...d});},
 'ux-export-events':()=>download('Pulp-actividad.json',{source:DEMO()?'Ejemplo local':'Operaciones de Pulp',events:activityData(S,R)})
 };
 document.addEventListener('input',event=>{const el=event.target;if(el.closest('form[data-form="ux-launch"]')&&el.name){S.ux.launch[el.name]=el.name==='symbol'?el.value.toUpperCase():el.value;const total=document.getElementById('ux-allocation-total');if(total)total.textContent=pct(allocationTotal(S.ux.launch));const name=document.getElementById('ux-preview-name');if(name)name.textContent=S.ux.launch.name||'Tu próximo proyecto';const symbol=document.getElementById('ux-preview-symbol');if(symbol)symbol.textContent=S.ux.launch.symbol||'TOKEN';save();}if(el.dataset.uxInput&&el.tagName==='INPUT'){const k=el.dataset.uxInput;if(Object.hasOwn(S.ux,k)){S.ux[k]=el.value;save();render();}}});
 document.addEventListener('change',event=>{const el=event.target;if(!el.dataset.uxInput)return;const k=el.dataset.uxInput;if(k==='radarSaved'&&el.value!==''){const v=S.ux.savedViews[Number(el.value)];if(v){Object.assign(S.ux,{radarQ:v.q,radarCategory:v.category,radarSort:v.sort,radarPeriod:v.period||'30d',radarOnlyFavorites:v.favorites});}}else if(Object.hasOwn(S.ux,k))S.ux[k]=el.value;save();render();});
 function setChart(node,index){const vs=JSON.parse(node.dataset.chartValues),ls=JSON.parse(node.dataset.chartLabels||'[]');const i=Math.max(0,Math.min(vs.length-1,index));node.dataset.chartIndex=i;const o=node.querySelector('output');if(o){o.hidden=false;o.textContent=(ls[i]?ls[i]+' · ':'')+(node.dataset.chartCurrency==='true'?money(vs[i]):number(vs[i],2));o.style.left=Math.max(10,Math.min(65,i*100/Math.max(1,vs.length-1)))+'%';}}
 document.addEventListener('pointermove',event=>{const n=event.target.closest('[data-chart-values]');if(n){const b=n.getBoundingClientRect(),vs=JSON.parse(n.dataset.chartValues);setChart(n,Math.round((event.clientX-b.left)/b.width*(vs.length-1)));}});
 document.addEventListener('keydown',event=>{const n=event.target.closest?.('[data-chart-values]');if(n&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const vs=JSON.parse(n.dataset.chartValues);setChart(n,event.key==='Home'?0:event.key==='End'?vs.length-1:Number(n.dataset.chartIndex||0)+(event.key==='ArrowRight'?1:-1));}if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(event.target.tagName)){const f=document.querySelector('.r-search input');if(f){event.preventDefault();f.focus();}}});
 return{actions,async onForm(kind,f){
 if(kind==='v4-alert'||kind==='v4-strategy'){
  if(kind==='v4-alert'&&!String(f.label||'').trim())throw Error('Ingresá un nombre para la regla.');
  if(kind==='v4-strategy'){
   if(!String(f.name||'').trim())throw Error('Ingresá un nombre para la estrategia.');
   if(!(Number(f.amount)>0)||!(Number(f.maxDailyUsdc)>=Number(f.amount)))throw Error('El límite diario debe ser igual o mayor al importe por operación.');
   if(!Number.isInteger(Number(f.intervalHours))||Number(f.intervalHours)<1||Number(f.intervalHours)>720)throw Error('El intervalo debe estar entre 1 y 720 horas.');
  }
  await api(kind==='v4-alert'?'v4/alerts/save':'v4/strategies/save',f,true);closeModal(true);clearData();toast('Borrador guardado. No se activaron operaciones ni avisos externos.');render();return;
 }
 if(kind==='ux-launch'){Object.assign(S.ux.launch,f);S.ux.launch.symbol=String(S.ux.launch.symbol).toUpperCase();const errors=validateLaunch(S.ux.launch,S.ux.launchStep);S.ux.launchErrors=errors;if(errors.length){save();render();return;}if(S.ux.launchStep<3)S.ux.launchStep++;else{const p=S.ux.launch,id=p.id||'ui-draft-'+Date.now();const draft={id,name:p.name,symbol:p.symbol,supply:p.supply,decimals:6,description:p.description,fixed:true,image:'',uri:'',updatedAt:Date.now(),uiPlan:{...p,id}};S.workspace.drafts=[draft,...S.workspace.drafts.filter(x=>x.id!==id)];const d=await api('account/save',S.workspace,true);S.workspace=d.workspace;S.ux.launch.id=id;S.ux.projectTab='drafts';toast('Borrador guardado. No se emitió ningún token.');location.hash='#/launchpad';}save();render();return;}
 if(kind==='ux-address'){const a=String(f.address||'').trim();const{address}=await import('/shared/solana.mjs');address(a);closeModal(true);S.watchAddress=a;S.forms.watch={address:a};toast(DEMO()?'Dirección validada. Las consultas externas están deshabilitadas.':'Dirección validada. Usá el explorador conectado.');render();}
 }};
}

